class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0
        for i, ch in enumerate(s):
            rev_index = ord('z') - ord(ch) + 1  # 'a' = 26, ..., 'z' = 1
            total += rev_index * (i + 1)        # string positions are 1-indexed
        return total
