class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Collect all substrings of s including the empty string
        subs_s = [""]
        n = len(s)
        for i in range(n):
            for j in range(i + 1, n + 1):
                subs_s.append(s[i:j])

        # Collect all substrings of t including the empty string
        subs_t = [""]
        m = len(t)
        for i in range(m):
            for j in range(i + 1, m + 1):
                subs_t.append(t[i:j])

        ans = 0
        # Try every concatenation s_sub + t_sub
        for a in subs_s:
            for b in subs_t:
                cand = a + b
                if cand == cand[::-1]:
                    ans = max(ans, len(cand))
        return ans
